using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class AEExteriorCamera {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");var cameras=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).ToArray();foreach(var c in cameras){c.clearFlags=CameraClearFlags.Skybox;c.backgroundColor=RenderSettings.fogColor;if(PrefabUtility.IsPartOfPrefabInstance(c))PrefabUtility.RecordPrefabInstancePropertyModifications(c);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{cameras=cameras.Select(c=>new{c.name,clearFlags=c.clearFlags.ToString()}).ToArray(),scope="1F camera scene override only; prefab, Player scripts and other scenes unchanged"};string o=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/Review/2026-11-12_1F_Abandoned/"));File.WriteAllText(o+"camera.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
